type View = "/app" | "/purchases" | "/manage" | "/receipts" | "/warranties" | "/returns" | "/spending" | "/ai" | "/notifications" | "/settings";
type Purchase = {
  id: number;
  productName: string;
  productImageUrl: string | null;
  brand: string | null;
  category: string | null;
  description: string | null;
  purchaseDate: Date | string;
  priceCents: number;
  currency: string;
  quantity: number;
  merchant: string | null;
  store: string | null;
  orderId: string | null;
  invoiceNumber: string | null;
  serialNumber: string | null;
  modelNumber: string | null;
  paymentMethod: string | null;
  warrantyMonths: number | null;
  warrantyStartDate: Date | string | null;
  warrantyExpiryDate: Date | string | null;
  returnPeriodDays: number | null;
  returnDeadline: Date | string | null;
  status: "active" | "archived" | "returned" | "claimed";
  receiptUrl: string | null;
  receiptKey: string | null;
  receiptFileName: string | null;
  notes: string | null;
  tags: string[];
  extractionConfidence: Record<string, number> | null;
};

const severityStyles = {
  critical: "border-rose-100 bg-rose-50 text-rose-700",
  urgent: "border-orange-100 bg-orange-50 text-orange-700",
  reminder: "border-amber-100 bg-amber-50 text-amber-700",
  safe: "border-emerald-100 bg-emerald-50 text-emerald-700",
};
const chartColors = ["#218b72", "#76ad36", "#dfa93c", "#df735d", "#5485b5"];

function currency(cents: number, code = "USD") { return new Intl.NumberFormat(undefined, { style: "currency", currency: code, maximumFractionDigits: 0 }).format(cents / 100); }
function date(value: Date | string | number | null | undefined) { return value ? new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", year: "numeric" }).format(new Date(value)) : "Not found"; }
function shortDate(value: Date | string | number | null | undefined) { return value ? new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" }).format(new Date(value)) : "—"; }
function daysTo(value: Date | string | number | null | undefined) { return value ? Math.ceil((new Date(value).getTime() - Date.now()) / 86_400_000) : null; }

function PageHeading({ eyebrow, title, text, action }: { eyebrow?: string; title: string; text: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[.14em] text-emerald-700">{eyebrow || "GUARD workspace"}</p><h1 className="mt-2 text-3xl font-semibold tracking-[-.05em] text-slate-950 sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{text}</p></div>{action}</div>; }

function EmptyState({ icon: Icon, title, text, action }: { icon: typeof PackagePlus; title: string; text: string; action?: React.ReactNode }) { return <div className="rounded-[1.5rem] border border-dashed border-slate-300 bg-white/70 px-6 py-12 text-center"><span className="mx-auto grid h-11 w-11 place-items-center rounded-2xl bg-emerald-50 text-emerald-700"><Icon className="h-5 w-5" /></span><h3 className="mt-4 font-semibold tracking-[-.02em] text-slate-800">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">{text}</p>{action && <div className="mt-5">{action}</div>}</div>; }

function MetricCard({ label, value, detail, tone = "neutral", icon: Icon }: { label: string; value: string; detail: string; tone?: "neutral" | "green" | "dark" | "orange"; icon: typeof PackagePlus }) { const tones = { neutral: "bg-white", green: "bg-[#eaf7ee]", dark: "bg-[#163d35] text-white", orange: "bg-[#fff5e8]" }; return <Card className={cn("overflow-hidden border-0 shadow-[0_10px_35px_rgba(22,61,53,.07)]", tones[tone])}><CardContent className="p-5"><div className="flex items-start justify-between"><div><p className={cn("text-xs font-medium", tone === "dark" ? "text-emerald-50/65" : "text-slate-500")}>{label}</p><p className="mt-3 text-3xl font-semibold tracking-[-.05em]">{value}</p></div><span className={cn("grid h-9 w-9 place-items-center rounded-xl", tone === "dark" ? "bg-white/10 text-lime-200" : "bg-white/80 text-emerald-700")}><Icon className="h-4 w-4" /></span></div><p className={cn("mt-6 text-xs", tone === "dark" ? "text-emerald-50/65" : "text-slate-500")}>{detail}</p></CardContent></Card>; }

function Dashboard({ openAdd }: { openAdd: () => void }) {
  const { data, isLoading } = trpc.purchases.dashboard.useQuery();
  const { data: recentPurchases = [] } = trpc.purchases.list.useQuery(useMemo(() => ({ filter: "all" as const }), []));
  const { data: upcomingReminders = [] } = trpc.notifications.list.useQuery();
  const [, setLocation] = useLocation();
  if (isLoading) return <DashboardLoading />;
  const hasPurchases = (data?.totalPurchases ?? 0) > 0;
  return <><PageHeading eyebrow="Your command center" title="A calmer way to keep track." text="GUARD brings the purchases that need attention forward — before a return window or warranty passes." action={<Button onClick={openAdd} className="h-10 rounded-xl bg-[#163d35] hover:bg-[#0e3129]"><Plus className="mr-1.5 h-4 w-4" />Add purchase</Button>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={ShoppingBag} label="Total purchases" value={String(data?.totalPurchases ?? 0)} detail="In your active workspace" /><MetricCard icon={Landmark} label="Total spending" value={currency(data?.totalSpendingCents ?? 0)} detail={`${currency(data?.monthSpendingCents ?? 0)} this month`} tone="dark" /><MetricCard icon={ShieldCheck} label="Active warranties" value={String(data?.activeWarranties ?? 0)} detail="Currently within coverage" tone="green" /><MetricCard icon={TimerReset} label="Upcoming deadlines" value={String(data?.deadlines ?? 0)} detail="Within the next 30 days" tone="orange" /></div>
    <section className="mt-8 grid gap-5 xl:grid-cols-[1.4fr_.6fr]"><Card className="border-slate-200/80 bg-white shadow-[0_10px_35px_rgba(22,61,53,.05)]"><CardContent className="p-5 sm:p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-base font-semibold tracking-[-.025em]">Needs your attention</p><p className="mt-1 text-sm text-slate-500">Ranked by urgency, so the next action is always clear.</p></div><button onClick={() => setLocation("/returns")} className="shrink-0 text-xs font-semibold text-emerald-700 hover:text-emerald-900">View deadlines</button></div><div className="mt-5 space-y-2.5">{hasPurchases && data?.attention?.length ? data.attention.map(item => <button key={`${item.purchaseId}-${item.kind}`} onClick={() => setLocation("/purchases")} className="flex w-full items-center gap-3 rounded-2xl border border-slate-100 p-3 text-left transition hover:border-emerald-100 hover:bg-[#fbfefb]"><span className={cn("grid h-9 w-9 shrink-0 place-items-center rounded-xl border", severityStyles[item.severity])}>{item.severity === "critical" ? <CircleAlert className="h-4 w-4" /> : item.severity === "safe" ? <Check className="h-4 w-4" /> : <TimerReset className="h-4 w-4" />}</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold text-slate-800">{item.productName}</span><span className="mt-0.5 block truncate text-xs text-slate-500">{item.title}</span></span><span className="hidden text-right sm:block"><span className="block text-xs font-semibold text-slate-600">{item.daysRemaining === null ? "Ready" : `${item.daysRemaining}d left`}</span><span className="mt-1 block text-[11px] text-emerald-700">{item.action}</span></span><ChevronRight className="h-4 w-4 shrink-0 text-slate-300" /></button>) : <EmptyState icon={ClipboardCheck} title="Your attention center is ready" text="Add a purchase or scan a receipt to let GUARD track warranty coverage, return windows, and missing details." action={<Button onClick={openAdd} size="sm" className="rounded-lg bg-[#163d35]"><Plus className="mr-1 h-3.5 w-3.5" />Add your first purchase</Button>} />}</div></CardContent></Card>
      <Card className="border-0 bg-[#163d35] text-white shadow-[0_14px_42px_rgba(22,61,53,.16)]"><CardContent className="flex h-full flex-col p-6"><span className="grid h-10 w-10 place-items-center rounded-xl bg-white/10 text-lime-200"><WandSparkles className="h-5 w-5" /></span><p className="mt-7 text-lg font-semibold tracking-[-.03em]">Ask GUARD AI what matters.</p><p className="mt-2 text-sm leading-6 text-emerald-50/70">Find purchases, check warranty coverage, and understand spending through your own records.</p><button onClick={() => setLocation("/ai")} className="mt-auto flex items-center justify-between rounded-xl bg-white/10 px-3.5 py-3 text-left text-sm transition hover:bg-white/15"><span>Open GUARD AI</span><ArrowUpRight className="h-4 w-4 text-lime-200" /></button></CardContent></Card></section>
    <section className="mt-5 grid gap-5 xl:grid-cols-2"><Card className="border-slate-200/80 bg-white"><CardContent className="p-5"><div className="flex items-center justify-between"><div><p className="font-semibold tracking-[-.02em] text-slate-800">Recent purchases</p><p className="mt-1 text-sm text-slate-500">Your latest saved items.</p></div><button onClick={() => setLocation("/purchases")} className="text-xs font-semibold text-emerald-700">View library</button></div><div className="mt-4 space-y-2">{recentPurchases.slice(0, 4).map(purchase => <button key={purchase.id} onClick={() => setLocation("/manage")} className="flex w-full items-center gap-3 rounded-xl bg-[#f8faf8] px-3 py-2.5 text-left transition hover:bg-emerald-50"><span className="grid h-8 w-8 place-items-center rounded-lg bg-white text-emerald-700"><ShoppingBag className="h-3.5 w-3.5" /></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium text-slate-700">{purchase.productName}</span><span className="block text-xs text-slate-400">{date(purchase.purchaseDate)} · {purchase.merchant || "Merchant not recorded"}</span></span><span className="text-sm font-semibold text-slate-800">{currency(purchase.priceCents * purchase.quantity, purchase.currency)}</span></button>)}{!recentPurchases.length && <p className="py-5 text-sm text-slate-500">Your latest purchases will appear here after you add one.</p>}</div></CardContent></Card><Card className="border-slate-200/80 bg-white"><CardContent className="p-5"><div className="flex items-center justify-between"><div><p className="font-semibold tracking-[-.02em] text-slate-800">Upcoming reminders</p><p className="mt-1 text-sm text-slate-500">Deadline and record alerts that still need review.</p></div><button onClick={() => setLocation("/notifications")} className="text-xs font-semibold text-emerald-700">Open alerts</button></div><div className="mt-4 space-y-2">{upcomingReminders.filter(item => !item.isRead).slice(0, 4).map(item => <button key={item.id} onClick={() => setLocation("/notifications")} className="flex w-full items-center gap-3 rounded-xl bg-[#f8faf8] px-3 py-2.5 text-left transition hover:bg-emerald-50"><span className={cn("grid h-8 w-8 place-items-center rounded-lg", severityStyles[item.severity])}><BellRing className="h-3.5 w-3.5" /></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium text-slate-700">{item.title}</span><span className="block truncate text-xs text-slate-400">{item.body}</span></span></button>)}{!upcomingReminders.filter(item => !item.isRead).length && <p className="py-5 text-sm text-slate-500">No unread reminders. GUARD will add time-sensitive alerts here.</p>}</div></CardContent></Card></section>
  </>;
}

function DashboardLoading() { return <div className="space-y-6"><div className="h-24 w-3/5 animate-pulse rounded-2xl bg-slate-200" /><div className="grid gap-4 sm:grid-cols-4">{Array.from({ length: 4 }).map((_, i) => <div key={i} className="h-40 animate-pulse rounded-2xl bg-slate-200" />)}</div><div className="h-72 animate-pulse rounded-2xl bg-slate-200" /></div>; }

function Purchases({ openAdd, defaultReceipt = false }: { openAdd: () => void; defaultReceipt?: boolean }) {
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<"all" | "active_warranty" | "warranty_soon" | "warranty_expired" | "returnable" | "return_expired" | "missing_info" | "archived">("all");
  const [receipt, setReceipt] = useState<File | null>(null);
  const input = useMemo(() => ({ query, filter }), [query, filter]);
  const { data: purchases, isLoading } = trpc.purchases.list.useQuery(input);
  const [, setLocation] = useLocation();
  const archive = trpc.purchases.archive.useMutation({ onSuccess: () => { toast.success("Purchase updated"); } });
  const remove = trpc.purchases.remove.useMutation({ onSuccess: () => { toast.success("Purchase removed"); } });
  return <><PageHeading eyebrow={defaultReceipt ? "Document workspace" : "Purchase library"} title={defaultReceipt ? "Bills & receipts" : "Everything you own, organized."} text={defaultReceipt ? "Upload a document, review AI-extracted details, and keep the proof of purchase close to every item." : "Search, filter, and manage every item you have added to your private workspace."} action={<Button onClick={openAdd} className="h-10 rounded-xl bg-[#163d35]"><Plus className="mr-1.5 h-4 w-4" />{defaultReceipt ? "Upload document" : "Add purchase"}</Button>} />
    {defaultReceipt && <><ReceiptDropzone onFile={setReceipt} /><CameraCapture onFile={setReceipt} /></>}
    <div className={cn("rounded-2xl border border-slate-200/80 bg-white p-3 shadow-[0_10px_35px_rgba(22,61,53,.04)]", defaultReceipt && "mt-6")}><div className="flex flex-col gap-3 md:flex-row md:items-center"><div className="relative min-w-0 flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><Input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search product, brand, merchant, serial number…" className="h-10 rounded-xl border-slate-200 bg-slate-50 pl-9 shadow-none" /></div><div className="flex gap-2 overflow-x-auto pb-0.5">{(["all", "active_warranty", "returnable", "missing_info", "archived"] as const).map(value => <button key={value} onClick={() => setFilter(value)} className={cn("whitespace-nowrap rounded-lg px-3 py-2 text-xs font-medium transition", filter === value ? "bg-[#163d35] text-white" : "bg-slate-100 text-slate-600 hover:bg-slate-200")}>{value === "all" ? "All purchases" : value === "active_warranty" ? "Active warranty" : value === "returnable" ? "Returnable" : value === "missing_info" ? "Missing info" : "Archived"}</button>)}</div></div>
      <div className="mt-4 overflow-x-auto">{isLoading ? <div className="p-8 text-center text-sm text-slate-500">Loading purchases…</div> : purchases?.length ? <table className="w-full min-w-[750px] text-left"><thead><tr className="border-y border-slate-100 text-[11px] font-semibold uppercase tracking-[.11em] text-slate-400"><th className="px-3 py-3">Purchase</th><th className="px-3 py-3">Price</th><th className="px-3 py-3">Coverage</th><th className="px-3 py-3">Return</th><th className="px-3 py-3">Status</th><th className="px-3 py-3" /></tr></thead><tbody>{purchases.map(purchase => <tr key={purchase.id} className="border-b border-slate-50 text-sm last:border-0"><td className="px-3 py-3.5"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#edf8ee] text-emerald-700">{purchase.receiptUrl ? <ReceiptText className="h-4 w-4" /> : <ShoppingBag className="h-4 w-4" />}</span><span><span className="block font-semibold text-slate-800">{purchase.productName}</span><span className="mt-0.5 block text-xs text-slate-500">{[purchase.brand, purchase.merchant].filter(Boolean).join(" · ") || "Needs details"}</span></span></div></td><td className="px-3 py-3.5 font-medium text-slate-700">{currency(purchase.priceCents, purchase.currency)}</td><td className="px-3 py-3.5 text-xs text-slate-600">{purchase.warrantyExpiryDate ? <><span className="block">Ends {shortDate(purchase.warrantyExpiryDate)}</span><span className={cn("mt-1 block", (daysTo(purchase.warrantyExpiryDate) ?? 0) < 31 ? "text-orange-600" : "text-emerald-700")}>{daysTo(purchase.warrantyExpiryDate)} days left</span></> : "Not found"}</td><td className="px-3 py-3.5 text-xs text-slate-600">{purchase.returnDeadline ? <><span className="block">Ends {shortDate(purchase.returnDeadline)}</span><span className={cn("mt-1 block", (daysTo(purchase.returnDeadline) ?? 0) < 4 ? "text-rose-600" : "text-emerald-700")}>{daysTo(purchase.returnDeadline)} days left</span></> : "—"}</td><td className="px-3 py-3.5"><Badge className={cn("border-0 text-[10px]", purchase.status === "active" ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-600")}>{purchase.status}</Badge></td><td className="px-3 py-3.5"><div className="flex justify-end gap-1"><button onClick={() => setLocation("/warranties")} aria-label="View purchase" className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700"><ChevronRight className="h-4 w-4" /></button><button onClick={() => archive.mutate({ id: purchase.id, archived: purchase.status !== "archived" })} aria-label="Archive purchase" className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700"><Archive className="h-3.5 w-3.5" /></button><button onClick={() => { if (confirm("Remove this purchase?")) remove.mutate({ id: purchase.id }); }} aria-label="Remove purchase" className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-rose-50 hover:text-rose-600"><Trash2 className="h-3.5 w-3.5" /></button></div></td></tr>)}</tbody></table> : <EmptyState icon={defaultReceipt ? FileSearch : PackagePlus} title={defaultReceipt ? "No documents yet" : "Start your purchase library"} text={defaultReceipt ? "Drop a JPG, PNG, or PDF above to begin the review process. You can also add the relevant details manually." : "Add your first purchase to start tracking warranties, return deadlines, and spending."} action={<Button onClick={openAdd} size="sm" className="rounded-lg bg-[#163d35]"><Plus className="mr-1 h-3.5 w-3.5" />Add purchase</Button>} />}</div></div>{receipt && <ReceiptReviewDialog file={receipt} onClose={() => setReceipt(null)} />}</>;
}

function ReceiptDropzone({ onFile }: { onFile: (file: File) => void }) { const [dragging, setDragging] = useState(false); const input = useRef<HTMLInputElement>(null); const accept = (file?: File) => { if (!file) return; if (!(["image/jpeg", "image/png", "application/pdf"] as string[]).includes(file.type)) return toast.error("Use a JPG, PNG, or PDF receipt."); if (file.size > 20 * 1024 * 1024) return toast.error("Choose a receipt smaller than 20 MB."); onFile(file); }; return <div role="button" tabIndex={0} onKeyDown={event => { if (event.key === "Enter") input.current?.click(); }} onClick={() => input.current?.click()} onDragEnter={() => setDragging(true)} onDragLeave={() => setDragging(false)} onDragOver={event => event.preventDefault()} onDrop={event => { event.preventDefault(); setDragging(false); accept(event.dataTransfer.files[0]); }} className={cn("group flex w-full cursor-pointer items-center gap-4 rounded-[1.35rem] border border-dashed p-5 text-left transition", dragging ? "border-emerald-500 bg-emerald-50" : "border-emerald-200 bg-[#f5fbf5] hover:border-emerald-400 hover:bg-[#eff9f0]")}><input ref={input} onClick={event => event.stopPropagation()} onChange={event => accept(event.target.files?.[0])} className="hidden" type="file" accept="image/jpeg,image/png,application/pdf" /><span className="grid h-11 w-11 place-items-center rounded-xl bg-white text-emerald-700 shadow-sm"><Upload className="h-5 w-5" /></span><span className="flex-1"><span className="block text-sm font-semibold text-slate-800">Upload a receipt, invoice, or bill</span><span className="mt-1 block text-xs text-slate-500">JPG, PNG, and PDF supported. GUARD will ask you to verify every detected detail.</span></span><ChevronRight className="h-4 w-4 text-emerald-600" /></div>; }

function ReceiptReviewDialog({ file, onClose }: { file: File; onClose: () => void }) { const utils = trpc.useUtils(); const extract = trpc.ai.extractReceipt.useMutation(); const create = trpc.purchases.create.useMutation({ onSuccess: () => { utils.purchases.invalidate(); toast.success("Extracted purchase saved"); onClose(); } }); const [stored, setStored] = useState<{ key: string; url: string; fileName: string } | null>(null); const [details, setDetails] = useState<any>(null); const [error, setError] = useState(""); const processing = extract.isPending || (!details && !!stored); const start = async () => { setError(""); try { const response = await fetch("/api/documents/upload", { method: "POST", headers: { "Content-Type": file.type, "x-file-name": file.name }, body: file }); const uploaded = await response.json(); if (!response.ok) throw new Error(uploaded.error || "Unable to upload this receipt."); setStored(uploaded); extract.mutate({ fileKey: uploaded.key, mimeType: file.type as "image/jpeg" | "image/png" | "application/pdf" }, { onSuccess: data => setDetails({ ...data, productName: data.productName || "", merchant: data.merchant || "", priceCents: data.priceCents ?? 0, purchaseDate: data.purchaseDate || new Date().toISOString().slice(0, 10), warrantyMonths: data.warrantyMonths ?? "", returnPeriodDays: data.returnPeriodDays ?? "" }), onError: failure => setError(failure.message) }); } catch (failure) { setError(failure instanceof Error ? failure.message : "Unable to process this receipt."); } }; const save = () => { if (!details?.productName) return toast.error("Confirm a product name before saving."); const purchasedAt = new Date(`${details.purchaseDate}T12:00:00`).getTime(); const warrantyMonths = details.warrantyMonths === "" ? null : Number(details.warrantyMonths); const returnDays = details.returnPeriodDays === "" ? null : Number(details.returnPeriodDays); create.mutate({ productName: details.productName, productImageUrl: null, brand: details.brand || null, category: details.category || null, description: null, purchaseDate: purchasedAt, priceCents: Number(details.priceCents) || 0, currency: details.currency || "USD", quantity: Number(details.quantity) || 1, merchant: details.merchant || null, store: null, orderId: details.orderId || null, invoiceNumber: details.invoiceNumber || null, serialNumber: details.serialNumber || null, modelNumber: details.modelNumber || null, paymentMethod: details.paymentMethod || null, warrantyMonths, warrantyStartDate: warrantyMonths ? purchasedAt : null, warrantyExpiryDate: warrantyMonths ? new Date(new Date(purchasedAt).setMonth(new Date(purchasedAt).getMonth() + warrantyMonths)).getTime() : null, returnPeriodDays: returnDays, returnDeadline: returnDays ? purchasedAt + returnDays * 86_400_000 : null, status: "active", receiptUrl: stored?.url || null, receiptKey: stored?.key || null, receiptFileName: stored?.fileName || file.name, notes: null, tags: [], extractionConfidence: details.confidence || {} }); }; const field = (key: string, label: string, type = "text") => <label className="block"><span className="flex items-center justify-between text-xs font-medium text-slate-600">{label}{details.confidence?.[key] !== undefined && <span className={cn("rounded-full px-2 py-0.5 text-[10px]", details.confidence[key] >= 85 ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-700")}>{details.confidence[key]}% confidence</span>}</span><Input type={type} value={details[key] ?? ""} onChange={event => setDetails((value: any) => ({ ...value, [key]: type === "number" ? Number(event.target.value) : event.target.value }))} className="mt-1.5 h-9 rounded-lg border-slate-200 text-sm" /></label>; return <div className="fixed inset-0 z-[70] flex items-end bg-slate-950/35 p-0 backdrop-blur-sm sm:items-center sm:justify-center sm:p-6"><div className="max-h-[92vh] w-full max-w-3xl overflow-auto rounded-t-[1.5rem] bg-white p-5 shadow-2xl sm:rounded-[1.5rem] sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[.13em] text-emerald-700">Receipt review</p><h2 className="mt-2 text-xl font-semibold tracking-[-.04em]">{details ? "Confirm extracted details" : "Extract your purchase details"}</h2><p className="mt-1 text-sm text-slate-500">{file.name} · {Math.max(1, Math.round(file.size / 1024))} KB</p></div><button onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></div>{!stored && !error && <div className="mt-8 text-center"><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-[#eaf7ee] text-emerald-700"><FileSearch className="h-6 w-6" /></span><p className="mt-4 text-sm font-semibold">Ready to read your document</p><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-500">GUARD will upload the file securely, extract visible details, and show a confidence score for each field it finds.</p><Button onClick={start} className="mt-6 h-10 rounded-xl bg-[#163d35]">Start extraction</Button></div>}{processing && <div className="py-10"><div className="mx-auto max-w-md space-y-3">{[["Upload", !!stored], ["Extract", extract.isPending], ["Review", false]].map(([label, active], index) => <div key={String(label)} className={cn("flex items-center gap-3 rounded-xl border p-3", active ? "border-emerald-200 bg-emerald-50" : "border-slate-100 bg-slate-50")}><span className={cn("grid h-7 w-7 place-items-center rounded-lg", active ? "bg-emerald-600 text-white" : "bg-slate-200 text-slate-500")}>{active ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : index + 1}</span><span className="text-sm font-medium text-slate-700">{label as string}</span><span className="ml-auto text-xs text-slate-400">{active ? "In progress" : "Waiting"}</span></div>)}</div></div>}{error && <div className="mt-6 rounded-xl border border-rose-100 bg-rose-50 p-4 text-sm text-rose-700"><p>{error}</p><Button onClick={start} size="sm" variant="outline" className="mt-3 border-rose-200 bg-white text-xs text-rose-700">Try again</Button></div>}{details && <><div className="mt-6 grid gap-4 sm:grid-cols-2">{field("productName", "Product name")}{field("merchant", "Merchant")}{field("purchaseDate", "Purchase date", "date")}{field("priceCents", "Total (smallest currency units)", "number")}{field("brand", "Brand")}{field("invoiceNumber", "Invoice / order number")}{field("serialNumber", "Serial number")}{field("warrantyMonths", "Warranty (months)", "number")}{field("returnPeriodDays", "Return period (days)", "number")}</div><div className="mt-6 flex justify-end gap-2"><Button onClick={onClose} variant="outline" className="h-9 rounded-lg border-slate-200 text-xs">Cancel</Button><Button onClick={save} disabled={create.isPending} className="h-9 rounded-lg bg-[#163d35] text-xs">{create.isPending && <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />}Save confirmed purchase</Button></div></>}</div></div>; }

function Warranties({ openAdd }: { openAdd: () => void }) { const { data: purchases, isLoading } = trpc.purchases.list.useQuery(useMemo(() => ({ filter: "active_warranty" as const }), [])); const [claimPurchase, setClaimPurchase] = useState<Purchase | null>(null); return <><PageHeading eyebrow="Coverage tracker" title="Your active warranties." text="See the coverage that is still in force, how much time remains, and the documents needed to make a claim." action={<Button onClick={openAdd} className="h-10 rounded-xl bg-[#163d35]"><Plus className="mr-1.5 h-4 w-4" />Add warranty</Button>} />{isLoading ? <DashboardLoading /> : purchases?.length ? <div className="grid gap-4 lg:grid-cols-2">{purchases.map(purchase => <WarrantyCard key={purchase.id} purchase={purchase} onClaim={() => setClaimPurchase(purchase)} />)}</div> : <EmptyState icon={ShieldCheck} title="No active warranties yet" text="Add a purchase with a warranty period and GUARD will calculate the coverage window automatically." action={<Button onClick={openAdd} size="sm" className="rounded-lg bg-[#163d35]"><Plus className="mr-1 h-3.5 w-3.5" />Add purchase</Button>} />}{claimPurchase && <ClaimAssistant purchase={claimPurchase} onClose={() => setClaimPurchase(null)} />}</>; }

function WarrantyCard({ purchase, onClaim }: { purchase: Purchase; onClaim: () => void }) { const remaining = Math.max(0, daysTo(purchase.warrantyExpiryDate) ?? 0); const total = Math.max(1, purchase.warrantyMonths ? purchase.warrantyMonths * 30 : remaining); const progress = Math.max(3, Math.min(100, (remaining / total) * 100)); return <Card className="overflow-hidden border-slate-200/80 bg-white shadow-[0_10px_35px_rgba(22,61,53,.04)]"><CardContent className="p-5"><div className="flex items-start justify-between gap-4"><div className="flex min-w-0 items-center gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#eaf7ee] text-emerald-700"><ShieldCheck className="h-5 w-5" /></span><div className="min-w-0"><p className="truncate font-semibold tracking-[-.02em] text-slate-800">{purchase.productName}</p><p className="mt-1 truncate text-xs text-slate-500">{purchase.brand || "Manufacturer not found"} · {purchase.serialNumber || "Serial not found"}</p></div></div><Badge className="border-0 bg-emerald-50 text-[10px] text-emerald-700">Active</Badge></div><div className="mt-7"><div className="flex items-end justify-between"><div><p className="text-2xl font-semibold tracking-[-.04em] text-slate-900">{remaining} days</p><p className="mt-1 text-xs text-slate-500">Coverage remaining</p></div><p className="text-xs text-slate-500">Expires {date(purchase.warrantyExpiryDate)}</p></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-gradient-to-r from-emerald-700 to-lime-400" style={{ width: `${progress}%` }} /></div></div><div className="mt-6 rounded-xl bg-[#f8faf8] p-3"><p className="text-[10px] font-semibold uppercase tracking-[.12em] text-slate-400">Warranty timeline</p><div className="mt-3 grid grid-cols-4 gap-1 text-center text-[10px]"><TimelineNode label="Purchase" value={shortDate(purchase.purchaseDate)} state="done" /><TimelineNode label="Return" value={purchase.returnDeadline ? shortDate(purchase.returnDeadline) : "—"} state="done" /><TimelineNode label="Today" value="Now" state="now" /><TimelineNode label="Expiry" value={shortDate(purchase.warrantyExpiryDate)} state="future" /></div></div><div className="mt-5 flex gap-2"><Button onClick={onClaim} className="h-9 flex-1 rounded-lg bg-[#163d35] text-xs hover:bg-[#0e3129]"><HandCoins className="mr-1.5 h-3.5 w-3.5" />Prepare warranty claim</Button><Button variant="outline" className="h-9 rounded-lg border-slate-200 bg-white text-xs"><FileText className="h-3.5 w-3.5" /></Button></div></CardContent></Card>; }
function TimelineNode({ label, value, state }: { label: string; value: string; state: "done" | "now" | "future" }) { return <div className="relative"><span className={cn("mx-auto block h-2.5 w-2.5 rounded-full ring-4", state === "done" ? "bg-emerald-600 ring-emerald-100" : state === "now" ? "bg-lime-500 ring-lime-100" : "bg-slate-300 ring-slate-100")} />{label !== "Expiry" && <span className="absolute left-[calc(50%+6px)] right-[calc(-50%+6px)] top-[4px] h-px bg-slate-200" />}<p className="mt-2 font-medium text-slate-600">{label}</p><p className="mt-0.5 text-slate-400">{value}</p></div>; }

function Returns({ openAdd }: { openAdd: () => void }) { const { data: purchases, isLoading } = trpc.purchases.list.useQuery(useMemo(() => ({ filter: "all" as const }), [])); const returnables = purchases?.filter(purchase => purchase.returnDeadline && purchase.status === "active").sort((a, b) => new Date(a.returnDeadline!).getTime() - new Date(b.returnDeadline!).getTime()) ?? []; return <><PageHeading eyebrow="Deadline tracker" title="Return windows, ranked by urgency." text="Know what can still be returned, what is about to close, and what has already passed." action={<Button onClick={openAdd} className="h-10 rounded-xl bg-[#163d35]"><Plus className="mr-1.5 h-4 w-4" />Add purchase</Button>} />{isLoading ? <DashboardLoading /> : returnables.length ? <div className="space-y-3">{returnables.map(purchase => { const remaining = daysTo(purchase.returnDeadline) ?? 0; const status = remaining < 0 ? "Expired" : remaining <= 3 ? "Ending Soon" : "Active"; const style = remaining < 0 ? "bg-slate-100 text-slate-600" : remaining <= 3 ? "bg-rose-50 text-rose-700" : "bg-emerald-50 text-emerald-700"; return <Card key={purchase.id} className="border-slate-200/80 bg-white shadow-[0_8px_25px_rgba(22,61,53,.04)]"><CardContent className="flex flex-wrap items-center gap-4 p-4"><span className={cn("grid h-10 w-10 place-items-center rounded-xl", remaining <= 3 ? "bg-rose-50 text-rose-600" : "bg-emerald-50 text-emerald-700")}><TimerReset className="h-4 w-4" /></span><div className="min-w-[180px] flex-1"><p className="font-semibold tracking-[-.02em] text-slate-800">{purchase.productName}</p><p className="mt-1 text-xs text-slate-500">Purchased {date(purchase.purchaseDate)} · {purchase.merchant || "Seller not found"}</p></div><div className="min-w-[120px]"><p className="text-xs text-slate-400">Deadline</p><p className="mt-1 text-sm font-semibold text-slate-700">{date(purchase.returnDeadline)}</p></div><div className="min-w-[90px]"><p className="text-xs text-slate-400">Time left</p><p className={cn("mt-1 text-sm font-semibold", remaining <= 3 ? "text-rose-600" : "text-emerald-700")}>{remaining < 0 ? "Expired" : `${remaining} days`}</p></div><Badge className={cn("border-0 text-[10px]", style)}>{status}</Badge></CardContent></Card>; })}</div> : <EmptyState icon={TimerReset} title="No return deadlines to track" text="Add a return period to a purchase and GUARD will keep the deadline in this prioritized list." action={<Button onClick={openAdd} size="sm" className="rounded-lg bg-[#163d35]"><Plus className="mr-1 h-3.5 w-3.5" />Add purchase</Button>} />}</>; }

function Spending() { const { data, isLoading } = trpc.purchases.spending.useQuery(); const categoryData = data?.byCategory ?? []; const monthData = data?.byMonth ?? []; return <><PageHeading eyebrow="Spending intelligence" title="Understand where your money went." text="GUARD turns the purchases you have saved into practical spending context — never investment advice." action={<button className="flex h-10 items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 text-xs font-medium text-slate-600"><Filter className="h-3.5 w-3.5" />All time</button>} />{isLoading ? <DashboardLoading /> : !data?.purchaseCount ? <EmptyState icon={CircleDollarSign} title="Your spending view will appear here" text="Once you save purchases, GUARD will show category trends, top merchants, and your highest-value purchases." /> : <><div className="grid gap-4 sm:grid-cols-3"><MetricCard icon={CircleDollarSign} label="Total spending" value={currency(data.totalCents)} detail="Across all active purchases" /><MetricCard icon={ReceiptText} label="Average purchase" value={currency(data.averageCents)} detail="Average value per purchase" tone="green" /><MetricCard icon={ShoppingBag} label="Purchases" value={String(data.purchaseCount)} detail="Recorded in GUARD" tone="orange" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.18fr_.82fr]"><ChartCard title="Monthly spending" subtitle="Purchase value over time"><ResponsiveContainer width="100%" height={260}><LineChart data={monthData}><XAxis dataKey="name" tickLine={false} axisLine={false} fontSize={11} /><YAxis tickLine={false} axisLine={false} fontSize={11} tickFormatter={value => `$${Math.round(value / 100)}`} /><Tooltip formatter={(value: number) => currency(value)} contentStyle={{ borderRadius: 12, borderColor: "#dce7de" }} /><Line type="monotone" dataKey="value" stroke="#218b72" strokeWidth={3} dot={{ r: 3, fill: "#218b72" }} /></LineChart></ResponsiveContainer></ChartCard><ChartCard title="By category" subtitle="Share of your recorded spending"><ResponsiveContainer width="100%" height={260}><PieChart><Pie data={categoryData} dataKey="value" nameKey="name" innerRadius={55} outerRadius={86} paddingAngle={4}>{categoryData.map((entry, index) => <Cell key={entry.name} fill={chartColors[index % chartColors.length]} />)}</Pie><Tooltip formatter={(value: number) => currency(value)} contentStyle={{ borderRadius: 12, borderColor: "#dce7de" }} /></PieChart></ResponsiveContainer><div className="-mt-2 flex flex-wrap justify-center gap-x-3 gap-y-1">{categoryData.map((entry, index) => <span key={entry.name} className="flex items-center gap-1.5 text-[11px] text-slate-500"><i className="h-2 w-2 rounded-full" style={{ background: chartColors[index % chartColors.length] }} />{entry.name}</span>)}</div></ChartCard></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><ChartCard title="Top merchants" subtitle="Where you have spent the most"><ResponsiveContainer width="100%" height={220}><BarChart data={data.byMerchant} layout="vertical" margin={{ left: 10 }}><XAxis type="number" hide /><YAxis dataKey="name" type="category" width={100} tickLine={false} axisLine={false} fontSize={11} /><Tooltip formatter={(value: number) => currency(value)} contentStyle={{ borderRadius: 12, borderColor: "#dce7de" }} /><Bar dataKey="value" radius={[0, 6, 6, 0]} fill="#76ad36" /></BarChart></ResponsiveContainer></ChartCard><Card className="border-slate-200/80 bg-white"><CardContent className="p-5"><p className="font-semibold tracking-[-.02em]">Highest-value purchases</p><p className="mt-1 text-sm text-slate-500">The purchases with the largest recorded values.</p><div className="mt-4 space-y-3">{data.topPurchases.map(purchase => <div key={purchase.id} className="flex items-center gap-3 rounded-xl bg-[#f8faf8] px-3 py-2.5"><span className="grid h-8 w-8 place-items-center rounded-lg bg-white text-emerald-700"><ShoppingBag className="h-3.5 w-3.5" /></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium text-slate-700">{purchase.productName}</span><span className="block text-xs text-slate-400">{purchase.category || "Uncategorized"}</span></span><span className="text-sm font-semibold text-slate-800">{currency(purchase.priceCents * purchase.quantity, purchase.currency)}</span></div>)}</div></CardContent></Card></div></>}</>; }
function ChartCard({ title, subtitle, children }: { title: string; subtitle: string; children: React.ReactNode }) { return <Card className="border-slate-200/80 bg-white"><CardContent className="p-5"><p className="font-semibold tracking-[-.02em]">{title}</p><p className="mt-1 text-sm text-slate-500">{subtitle}</p><div className="mt-4">{children}</div></CardContent></Card>; }

function GuardAI() { const [messages, setMessages] = useState<Message[]>([{ role: "assistant", content: "I’m **GUARD AI**. Ask about the purchases you have saved, warranty coverage, return windows, or spending. I’ll clearly distinguish stored facts from information that still needs verification." }]); const chat = trpc.ai.chat.useMutation({ onSuccess: response => setMessages(previous => [...previous, { role: "assistant", content: response.answer }]), onError: failure => { toast.error("GUARD AI could not answer right now."); setMessages(previous => [...previous, { role: "assistant", content: `I couldn’t complete that request: ${failure.message}` }]); } }); const send = (content: string) => { setMessages(previous => [...previous, { role: "user", content }]); chat.mutate({ message: content }); }; return <><PageHeading eyebrow="Purchase intelligence" title="Talk to GUARD AI." text="Ask natural-language questions about the purchases you have saved. Answers remain grounded in the data in your workspace." /><div className="grid gap-5 xl:grid-cols-[1fr_290px]"><AIChatBox messages={messages} onSendMessage={send} isLoading={chat.isPending} height="620px" placeholder="Ask about your receipts, warranties, returns, or spending…" suggestedPrompts={["Which warranties expire this month?", "What can I still return?", "How much did I spend on electronics?", "What should I do if my headphones stopped working?"]} className="rounded-[1.25rem] border-slate-200 shadow-[0_10px_35px_rgba(22,61,53,.05)]" /><Card className="border-0 bg-[#163d35] text-white"><CardContent className="p-5"><span className="grid h-9 w-9 place-items-center rounded-xl bg-white/10 text-lime-200"><Sparkles className="h-4 w-4" /></span><p className="mt-5 font-semibold tracking-[-.02em]">What should I do?</p><p className="mt-2 text-sm leading-6 text-emerald-50/70">Describe a product problem. GUARD will look for the matching purchase and explain the stored warranty status.</p><div className="mt-5 rounded-xl bg-white/10 p-3 text-xs leading-5 text-emerald-50/80">Example: “My headphones stopped working.”</div><p className="mt-6 text-[11px] leading-5 text-emerald-50/50">GUARD AI uses your saved purchase records. It does not submit real warranty claims.</p></CardContent></Card></div></>; }

function Notifications() { const utils = trpc.useUtils(); const { data: items, isLoading } = trpc.notifications.list.useQuery(); const { data: duplicates } = trpc.purchases.duplicates.useQuery(); const markRead = trpc.notifications.markRead.useMutation({ onSuccess: () => toast.success("Notification marked as read") }); const merge = trpc.purchases.mergeDuplicate.useMutation({ onSuccess: () => { utils.purchases.invalidate(); toast.success("Duplicate purchases merged"); } }); const keepSeparate = trpc.purchases.keepSeparate.useMutation({ onSuccess: () => { utils.purchases.invalidate(); toast.success("Purchases kept as separate records"); } }); return <><PageHeading eyebrow="Notification center" title="Stay ahead of purchase events." text="Return deadlines, warranty dates, duplicate warnings, and incomplete records all live in one reviewable place." />{duplicates?.length ? <section className="mb-6"><p className="mb-2 text-xs font-semibold uppercase tracking-[.12em] text-amber-700">Possible duplicate purchases</p><div className="space-y-3">{duplicates.map(match => <Card key={`${match.first.id}-${match.second.id}`} className="border-amber-100 bg-amber-50/60"><CardContent className="p-4"><div className="flex flex-wrap items-start gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-white text-amber-700"><Copy className="h-4 w-4" /></span><div className="min-w-[190px] flex-1"><p className="text-sm font-semibold text-slate-800">{match.first.productName} may be duplicated</p><p className="mt-1 text-xs leading-5 text-slate-500">{match.reason}</p><p className="mt-2 text-xs font-medium text-slate-600">{match.first.merchant || "Unknown merchant"} · {currency(match.first.priceCents, match.first.currency)} · {date(match.first.purchaseDate)}</p></div><div className="flex gap-2"><Button onClick={() => merge.mutate({ keepId: match.first.id, removeId: match.second.id })} disabled={merge.isPending || keepSeparate.isPending} className="h-8 rounded-lg bg-[#163d35] text-xs">Merge</Button><Button onClick={() => keepSeparate.mutate({ firstId: match.first.id, secondId: match.second.id })} disabled={merge.isPending || keepSeparate.isPending} variant="outline" className="h-8 rounded-lg border-amber-200 bg-white text-xs">Keep Separate</Button></div></div></CardContent></Card>)}</div></section> : null}{isLoading ? <DashboardLoading /> : items?.length ? <div className="space-y-3">{items.map(item => <Card key={item.id} className={cn("border-slate-200/80 bg-white", !item.isRead && "border-emerald-200")}><CardContent className="flex items-start gap-3 p-4"><span className={cn("mt-0.5 grid h-9 w-9 place-items-center rounded-xl border", severityStyles[item.severity])}>{item.type === "duplicate" ? <Copy className="h-4 w-4" /> : <BellRing className="h-4 w-4" />}</span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold text-slate-800">{item.title}</span><span className="mt-1 block text-sm leading-6 text-slate-500">{item.body}</span><span className="mt-2 block text-xs text-slate-400">{date(item.eventAt || item.createdAt)}</span></span>{!item.isRead && <Button onClick={() => markRead.mutate({ id: item.id })} variant="outline" size="sm" className="h-8 rounded-lg border-slate-200 text-xs">Mark read</Button>}</CardContent></Card>)}</div> : !duplicates?.length && <EmptyState icon={Inbox} title="Nothing new to review" text="GUARD will place alerts here when a deadline approaches, a record is incomplete, or a possible duplicate needs your decision." />}</>; }

function Settings() { const { data, isLoading } = trpc.notifications.preferences.useQuery(); const update = trpc.notifications.updatePreferences.useMutation({ onSuccess: () => toast.success("Notification preferences saved") }); const [reminders, setReminders] = useState<number[] | null>(null); const active = reminders ?? data?.reminderDays ?? [30, 14, 7, 3, 1]; const enabled = Boolean(data?.notificationsEnabled ?? 1); const toggleDay = (day: number) => setReminders(previous => { const actual = previous ?? data?.reminderDays ?? [30, 14, 7, 3, 1]; return actual.includes(day) ? actual.filter(value => value !== day) : [...actual, day].sort((a, b) => b - a); }); return <><PageHeading eyebrow="Workspace controls" title="Set how GUARD keeps in touch." text="Choose when deadline reminders are generated. Scheduled delivery becomes available once the project is deployed." /><div className="grid gap-5 lg:grid-cols-[1fr_.65fr]"><Card className="border-slate-200/80 bg-white"><CardContent className="p-5"><div className="flex items-center justify-between"><div><p className="font-semibold tracking-[-.02em]">Purchase notifications</p><p className="mt-1 text-sm text-slate-500">Enable deadline and incomplete-record reminders.</p></div><Switch disabled={isLoading} checked={enabled} onCheckedChange={value => update.mutate({ reminderDays: active, notificationsEnabled: value })} /></div><div className="mt-7 border-t border-slate-100 pt-5"><p className="text-sm font-semibold text-slate-700">Reminder timing</p><p className="mt-1 text-xs leading-5 text-slate-500">Select the days before a return deadline or warranty expiry when GUARD should create an alert.</p><div className="mt-4 flex flex-wrap gap-2">{[30, 14, 7, 3, 1].map(day => <button key={day} onClick={() => toggleDay(day)} className={cn("rounded-xl border px-3 py-2 text-xs font-semibold transition", active.includes(day) ? "border-emerald-500 bg-emerald-50 text-emerald-700" : "border-slate-200 bg-white text-slate-500 hover:border-slate-300")}>{active.includes(day) && <Check className="mr-1 inline h-3 w-3" />}{day} day{day === 1 ? "" : "s"}</button>)}</div><Button disabled={update.isPending} onClick={() => update.mutate({ reminderDays: active, notificationsEnabled: enabled })} className="mt-5 h-9 rounded-lg bg-[#163d35] text-xs">{update.isPending && <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />}Save timing</Button></div></CardContent></Card><Card className="border-0 bg-[#eaf7ee]"><CardContent className="p-5"><span className="grid h-9 w-9 place-items-center rounded-xl bg-white text-emerald-700"><ShieldCheck className="h-4 w-4" /></span><p className="mt-5 font-semibold tracking-[-.02em] text-emerald-950">Your purchase data is personal.</p><p className="mt-2 text-sm leading-6 text-emerald-900/65">GUARD scopes purchases, documents, and notifications to your signed-in workspace. AI answers should be based only on the data you have saved.</p></CardContent></Card></div></>; }

function ClaimAssistant({ purchase, onClose }: { purchase: Purchase; onClose: () => void }) { const [problem, setProblem] = useState(""); const [editing, setEditing] = useState(false); const [claim, setClaim] = useState(""); const createClaim = () => { const text = `Subject: Warranty service request — ${purchase.productName}\n\nHello ${purchase.brand || "Support Team"},\n\nI am requesting warranty service for my ${purchase.productName}${purchase.modelNumber ? ` (model ${purchase.modelNumber})` : ""}.${purchase.serialNumber ? ` The serial number is ${purchase.serialNumber}.` : ""}\n\nPurchase date: ${date(purchase.purchaseDate)}\n${purchase.invoiceNumber ? `Invoice/order reference: ${purchase.invoiceNumber}\n` : ""}Warranty expiry: ${date(purchase.warrantyExpiryDate)}\n\nProblem description:\n${problem || "Please describe the issue."}\n\nPlease let me know the next steps for assessment or repair. I can provide the stored proof of purchase if required.\n\nKind regards`; setClaim(text); }; const download = () => { const blob = new Blob([claim], { type: "text/plain" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${purchase.productName.replace(/\W+/g, "-").toLowerCase()}-warranty-claim.txt`; anchor.click(); URL.revokeObjectURL(url); }; return <div className="fixed inset-0 z-[60] flex items-end bg-slate-950/35 p-0 backdrop-blur-sm sm:items-center sm:justify-center sm:p-6"><div className="max-h-[90vh] w-full max-w-2xl overflow-auto rounded-t-[1.5rem] bg-white p-5 shadow-2xl sm:rounded-[1.5rem] sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[.13em] text-emerald-700">Warranty Claim Assistant</p><h2 className="mt-2 text-xl font-semibold tracking-[-.04em]">Prepare a service request</h2></div><button onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></div><div className="mt-5 grid gap-2 rounded-xl bg-[#f8faf8] p-3 text-xs text-slate-600 sm:grid-cols-2"><span><b>Product:</b> {purchase.productName}</span><span><b>Warranty expiry:</b> {date(purchase.warrantyExpiryDate)}</span><span><b>Serial:</b> {purchase.serialNumber || "Not found"}</span><span><b>Invoice:</b> {purchase.invoiceNumber || "Not found"}</span></div><Label className="mt-5 block text-sm font-medium text-slate-700">Describe the problem</Label><Textarea value={problem} onChange={event => setProblem(event.target.value)} placeholder="For example: The left earcup no longer produces sound after normal use." className="mt-2 min-h-24 rounded-xl border-slate-200" /><Button onClick={createClaim} className="mt-3 h-9 rounded-lg bg-[#163d35] text-xs">Generate claim text</Button>{claim && <><Textarea value={claim} readOnly={!editing} onChange={event => setClaim(event.target.value)} className="mt-5 min-h-56 rounded-xl border-slate-200 bg-slate-50 font-mono text-xs leading-5" /><div className="mt-3 flex flex-wrap gap-2"><Button onClick={() => navigator.clipboard.writeText(claim).then(() => toast.success("Claim copied"))} variant="outline" className="h-9 rounded-lg border-slate-200 text-xs"><Copy className="mr-1.5 h-3.5 w-3.5" />Copy</Button><Button onClick={download} variant="outline" className="h-9 rounded-lg border-slate-200 text-xs"><Download className="mr-1.5 h-3.5 w-3.5" />Download</Button><Button onClick={() => setEditing(value => !value)} variant="outline" className={cn("h-9 rounded-lg border-slate-200 text-xs", editing && "border-emerald-400 bg-emerald-50 text-emerald-700")}><Pencil className="mr-1.5 h-3.5 w-3.5" />Edit</Button></div></>}</div></div>; }

function AddPurchaseDialog({ open, onClose }: { open: boolean; onClose: () => void }) { const utils = trpc.useUtils(); const create = trpc.purchases.create.useMutation({ onSuccess: () => { utils.purchases.invalidate(); toast.success("Purchase saved to GUARD"); onClose(); } }); const [form, setForm] = useState({ productName: "", brand: "", category: "", price: "", merchant: "", purchaseDate: new Date().toISOString().slice(0, 10), warrantyMonths: "", returnDays: "", serialNumber: "", invoiceNumber: "", tags: "" }); if (!open) return null; const update = (key: keyof typeof form, value: string) => setForm(previous => ({ ...previous, [key]: value })); const save = () => { if (!form.productName.trim() || !form.price) { toast.error("Add a product name and purchase price first."); return; } const bought = new Date(`${form.purchaseDate}T12:00:00`).getTime(); const warrantyMonths = Number(form.warrantyMonths) || null; const returnDays = Number(form.returnDays) || null; create.mutate({ productName: form.productName, brand: form.brand || null, category: form.category || null, priceCents: Math.round(Number(form.price) * 100), currency: "USD", quantity: 1, merchant: form.merchant || null, purchaseDate: bought, warrantyMonths, warrantyStartDate: warrantyMonths ? bought : null, warrantyExpiryDate: warrantyMonths ? new Date(new Date(bought).setMonth(new Date(bought).getMonth() + warrantyMonths)).getTime() : null, returnPeriodDays: returnDays, returnDeadline: returnDays ? bought + returnDays * 86_400_000 : null, serialNumber: form.serialNumber || null, invoiceNumber: form.invoiceNumber || null, tags: form.tags.split(",").map(tag => tag.trim()).filter(Boolean), status: "active", productImageUrl: null, description: null, store: null, orderId: null, modelNumber: null, paymentMethod: null, receiptUrl: null, receiptKey: null, receiptFileName: null, notes: null, extractionConfidence: null }); }; return <div className="fixed inset-0 z-[60] flex items-end bg-slate-950/35 p-0 backdrop-blur-sm sm:items-center sm:justify-center sm:p-6"><div className="max-h-[92vh] w-full max-w-2xl overflow-auto rounded-t-[1.5rem] bg-white p-5 shadow-2xl sm:rounded-[1.5rem] sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[.13em] text-emerald-700">New purchase</p><h2 className="mt-2 text-xl font-semibold tracking-[-.04em]">Add what you bought</h2><p className="mt-1 text-sm text-slate-500">You can complete additional receipt and warranty information later.</p></div><button onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Product name *"><Input value={form.productName} onChange={event => update("productName", event.target.value)} placeholder="e.g. Wireless headphones" /></Field><Field label="Purchase price *"><Input value={form.price} onChange={event => update("price", event.target.value)} type="number" min="0" step="0.01" placeholder="0.00" /></Field><Field label="Purchase date"><Input value={form.purchaseDate} onChange={event => update("purchaseDate", event.target.value)} type="date" /></Field><Field label="Merchant"><Input value={form.merchant} onChange={event => update("merchant", event.target.value)} placeholder="e.g. Amazon" /></Field><Field label="Brand"><Input value={form.brand} onChange={event => update("brand", event.target.value)} placeholder="e.g. Sony" /></Field><Field label="Category"><Input value={form.category} onChange={event => update("category", event.target.value)} placeholder="e.g. Electronics" /></Field><Field label="Warranty duration (months)"><Input value={form.warrantyMonths} onChange={event => update("warrantyMonths", event.target.value)} type="number" min="0" placeholder="e.g. 24" /></Field><Field label="Return period (days)"><Input value={form.returnDays} onChange={event => update("returnDays", event.target.value)} type="number" min="0" placeholder="e.g. 30" /></Field><Field label="Serial number"><Input value={form.serialNumber} onChange={event => update("serialNumber", event.target.value)} placeholder="Optional" /></Field><Field label="Invoice / order number"><Input value={form.invoiceNumber} onChange={event => update("invoiceNumber", event.target.value)} placeholder="Optional" /></Field></div><Field label="Tags"><Input value={form.tags} onChange={event => update("tags", event.target.value)} placeholder="Comma-separated, e.g. work, audio" /></Field><div className="mt-6 flex justify-end gap-2"><Button variant="outline" onClick={onClose} className="h-9 rounded-lg border-slate-200 text-xs">Cancel</Button><Button disabled={create.isPending} onClick={save} className="h-9 rounded-lg bg-[#163d35] text-xs">{create.isPending && <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />}Save purchase</Button></div></div></div>; }
function CameraCapture({ onFile }: { onFile: (file: File) => void }) { const input = useRef<HTMLInputElement>(null); const accept = (file?: File) => { if (!file) return; if (!(["image/jpeg", "image/png"] as string[]).includes(file.type)) return toast.error("Use a JPG or PNG image from your camera."); onFile(file); }; return <div className="mt-3 flex items-center justify-between rounded-xl border border-slate-200 bg-white px-4 py-3"><span><span className="block text-sm font-medium text-slate-700">Capture a receipt with your camera</span><span className="mt-0.5 block text-xs text-slate-500">Available on supported mobile devices.</span></span><><input ref={input} className="hidden" type="file" capture="environment" accept="image/jpeg,image/png" onChange={event => accept(event.target.files?.[0])} /><Button type="button" variant="outline" onClick={() => input.current?.click()} className="h-8 rounded-lg border-slate-200 text-xs">Use camera</Button></></div>; }

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="mt-4 block text-sm font-medium text-slate-700"><span>{label}</span><span className="mt-1.5 block">{children}</span></label>; }

export default function GuardApp({ view }: { view: View }) { const [addOpen, setAddOpen] = useState(false); const openAdd = () => setAddOpen(true); return <><>{view === "/app" && <Dashboard openAdd={openAdd} />}{view === "/purchases" && <Purchases openAdd={openAdd} />}{view === "/manage" && <PurchaseEditor />}{view === "/receipts" && <Purchases openAdd={openAdd} defaultReceipt />}{view === "/warranties" && <Warranties openAdd={openAdd} />}{view === "/returns" && <Returns openAdd={openAdd} />}{view === "/spending" && <Spending />}{view === "/ai" && <GuardAI />}{view === "/notifications" && <Notifications />}{view === "/settings" && <Settings />}</><AddPurchaseDialog open={addOpen} onClose={() => setAddOpen(false)} /></>; }
